struct SkillFixture final:NavalGunnerySkillRead {
 const CommonStore& common;Integer current_level=2,historical_level=2;bool wrong_world=false;
 explicit SkillFixture(const CommonStore& c):common(c){}
 NavalGunnerySkillObservation result(const StableId& actor,const StableId& before)const{NavalGunnerySkillObservation r;r.source_identity=common.state().identity;if(wrong_world)r.source_identity.world_id[0]^=1;r.actor_id=actor;r.authored_actor_id=actor;r.before_fact_id=before;r.observed_tick=1;r.level=before.empty()?current_level:historical_level;r.experience=100;return r;}
 Outcome<NavalGunnerySkillObservation> current_naval_skill(const StableId& actor)const override{return {true,result(actor,{}),{}};}
 Outcome<NavalGunnerySkillObservation> naval_skill_before(const StableId& actor,const StableId& before)const override{return {true,result(actor,before),{}};}
};
