int main(){try{GunneryFixture f;DynamicStepInput phase;phase.from_tick=0;phase.to_tick=1;f.skills.wrong_world=true;const auto next=f.common.state().next_instance_id;check(!record_naval_gunnery_preparation(f.common,f.military,f.assets,f.gunnery,f.contact,f.frame,f.skills,phase).ok&&f.common.state().next_instance_id==next,"foreign reader rejects before new ID");f.skills.wrong_world=false;
 auto id=take(record_naval_gunnery_preparation(f.common,f.military,f.assets,f.gunnery,f.contact,f.frame,f.skills,phase));check(id=="naval_skill:11"&&f.gunnery.preparations.size()==1,"single real Common preparation boundary");const auto prepared=f.gunnery.preparations.front();check(validate_naval_gunnery_initial_bindings(prepared,f.frame).ok,"exact initial original bindings");check(!record_naval_gunnery_preparation(f.common,f.military,f.assets,f.gunnery,f.contact,f.frame,f.skills,phase).ok,"same contact cannot prepare twice");
 NavalBattleState history;history.contacts={f.contact};NavalBattleRecord b;b.frame=f.frame;b.contact_source_id=f.contact.id;b.created_tick=1;history.battles={b};f.common.state().identity.tick=1;check(validate_naval_gunnery_history(f.common,f.gunnery,history,f.skills).ok,"same exact preparation history accepted");f.skills.current_level=9;check(validate_naval_gunnery_history(f.common,f.gunnery,history,f.skills).ok,"later current skill does not backfill old preparation");auto q=take(preview_naval_gunnery(f.assets,f.catalog,f.policy,f.catalog_military,prepared,f.frame,"unit0","unit2"));check(q.hull_damage==16&&q.naval_level==2&&q.personnel.hit_chance==100,"frozen2 level means16 hull and original personnel chance");
 check(validate_naval_gunnery_sources(f.common,f.gunnery,history).ok,"early structure gate accepts exact original source without XP reader");f.skills.historical_level=3;check(!validate_naval_gunnery_history(f.common,f.gunnery,history,f.skills).ok,"changed historical skill rejects despite valid shape");f.skills.historical_level=2;auto wrong=prepared;wrong.captains[0].captain_actor_id="captainX";check(!validate_naval_gunnery_initial_bindings(wrong,f.frame).ok,"foreign captain cannot borrow preparation");
 auto captured_frame=f.frame;captured_frame.bindings[0].vessel_id="captured-vessel";check(validate_naval_gunnery_frame_source(prepared,captured_frame).ok,"source keeps original captain skill after separately validated capture binding");check(!validate_naval_gunnery_initial_bindings(prepared,captured_frame).ok,"initial entry binding never accepts the later captured vessel");captured_frame.units[0].commander_actor_id="other";check(!validate_naval_gunnery_frame_source(prepared,captured_frame).ok,"later vessel does not permit changing original captain skill source");auto missing=f.gunnery;missing.preparations.clear();check(!validate_naval_gunnery_sources(f.common,missing,history).ok,"mechanical history cannot omit preparation");
 NavalCombatRules rules;rules.gunnery=f.policy;auto orders=f.holds();orders[0].second={"hull_attack","unit2",{0,0},0};orders[2].second={"hull_attack","unit0",{2,0},3};Integer draws=0;MilitaryBattleRandom random=[&](StableId&,StableId& state,Integer lo,Integer hi)->Outcome<Integer>{++draws;state=std::to_string(draws);if(lo!=1||hi!=100)return {false,{},common_failure("UnexpectedDraw").error};return {true,1,{}};};auto result=take(resolve_naval_combat(f.assets,f.catalog,rules,f.catalog_military,f.frame,orders,"0","0",random,&prepared));check(draws==2&&result.assets.vessels[0].integrity==64&&result.assets.vessels[2].integrity==64,"simultaneous hostile attacks use two original random draws");for(std::size_t i=0;i<f.frame.units.size();++i){const auto& u=result.frame.units[i];check(u.member_ids==f.frame.units[i].member_ids&&u.fit.size()+u.wounded.size()+u.dead.size()+u.captured.size()+u.deserted.size()==u.member_ids.size(),"personnel split conserves every original token");check(result.assets.vessels[i].owner.id==f.assets.vessels[i].owner.id,"hull fire never transfers ownership");}check(result.capture_claims.empty(),"gunfire loss alone grants no automatic capture claim");check(f.assets.vessels[0].integrity==80&&f.frame.units[0].fit.size()==10,"pure resolution leaves originals untouched");NavalCombatRules old;check(!resolve_naval_combat(f.assets,f.catalog,old,f.catalog_military,f.frame,orders,"0","0",random).ok,"legacy profile rejects hull attack");
 auto json=naval_gunnery_codec::encode(f.gunnery);auto decoded=take(naval_gunnery_codec::decode(json));CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);writer.naval_codec_version=6;check(naval_gunnery_codec::visit(writer,decoded).ok&&writer.finish().ok,"Naval6 source segment encodes");NavalGunneryState restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));reader.naval_codec_version=6;check(naval_gunnery_codec::visit(reader,restored).ok&&reader.finish().ok,"Naval6 source segment decodes");check(take(render_boundary_json(json))==take(render_boundary_json(naval_gunnery_codec::encode(restored))),"ordered source bytes preserve complete payload");auto bad=json;bad.as<BoundaryValue::Dict>()->push_back({"preparations",BoundaryValue{BoundaryValue::Array{}}});check(!naval_gunnery_codec::decode(bad).ok,"duplicate root key rejects");CodecVisitor::Buffer legacy;CodecVisitor old_writer(legacy);old_writer.naval_codec_version=5;check(!naval_gunnery_codec::visit(old_writer,restored).ok&&legacy.empty(),"oldNaval5 cannot append even empty new segment");
 std::cout<<"NAVAL_GUNNERY="<<checks<<" FAILURES=0 SCOPE=DOMAIN_TYPED_GROWTH_FIXTURE_ONLY\n";return 0;
 }catch(const std::exception& e){std::cerr<<"NAVAL_GUNNERY_FAIL checks="<<checks<<" "<<e.what()<<'\n';return 1;}}
